//! Typing text over HID ourselves, per keyboard layout, instead of the firmware's
//! `/api/hid/print`.
//!
//! The firmware sends AltGr as Left Ctrl + Right Alt, which Windows accepts but Linux and
//! macOS read as a Ctrl shortcut: `| @ \ [ ] { } ~ €` on German (and similar layouts) are
//! lost there. Here AltGr is Right Alt alone (Windows accepts that too) and Option on macOS.
//!
//! Layout tables come from Unicode CLDR (`data.rs`, generated by `scripts/gen-layouts.py`).
//! Windows layouts also serve Linux targets; firmware screens (BIOS) read raw US scancodes,
//! so they always get the US layout.

mod data;

use crate::hid::HidCommand;

/// Which OS's version of a layout to use.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Platform {
    /// Windows layouts; Linux's xkb layouts match them for typed characters.
    Windows,
    Mac,
}

/// One key stroke: index into the key code table, and modifier bits.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct S(pub(crate) u8, pub(crate) u8);

/// A layout's characters, sorted, with the strokes that type each.
type Table = &'static [(char, &'static [S])];

const SHIFT: u8 = 1;
const ALTGR: u8 = 2;

#[derive(Debug, Clone, Copy)]
pub struct Layout {
    pub name: &'static str,
    pub platform: Platform,
    entries: Table,
}

/// The layout for a device keymap name (`de`, `en-us`, …), if we have it.
pub fn layout(name: &str, platform: Platform) -> Option<Layout> {
    data::LAYOUTS
        .iter()
        .find(|(n, p, _)| *n == name && *p == platform)
        .map(|&(name, platform, entries)| Layout {
            name,
            platform,
            entries,
        })
}

/// Device keymap names we have tables for.
pub fn names() -> Vec<&'static str> {
    let mut v: Vec<_> = data::LAYOUTS.iter().map(|(n, _, _)| *n).collect();
    v.dedup();
    v
}

/// Key presses for one character, or `None` if the layout cannot produce it.
pub type Keys = Vec<HidCommand>;

impl Layout {
    /// The strokes for `ch`, as `(key code, shift, altgr)`.
    pub fn strokes(&self, ch: char) -> Option<Vec<(&'static str, bool, bool)>> {
        let i = self.entries.binary_search_by_key(&ch, |(c, _)| *c).ok()?;
        Some(
            self.entries[i]
                .1
                .iter()
                .map(|s| {
                    (
                        data::CODES[usize::from(s.0)],
                        s.1 & SHIFT != 0,
                        s.1 & ALTGR != 0,
                    )
                })
                .collect(),
        )
    }

    /// HID commands that type `ch` (press and release, modifiers included).
    pub fn keys(&self, ch: char) -> Option<Keys> {
        let strokes = match ch {
            '\n' => vec![("Enter", false, false)],
            '\t' => vec![("Tab", false, false)],
            '\r' => return Some(Vec::new()),
            _ => self.strokes(ch)?,
        };
        let altgr_key = match self.platform {
            Platform::Windows => "AltRight",
            Platform::Mac => "AltLeft",
        };
        let mut out = Vec::new();
        for (code, shift, altgr) in strokes {
            let mods: Vec<&'static str> = [(shift, "ShiftLeft"), (altgr, altgr_key)]
                .into_iter()
                .filter_map(|(on, k)| on.then_some(k))
                .collect();
            for &m in &mods {
                out.push(HidCommand::Key {
                    code: m,
                    pressed: true,
                });
            }
            out.push(HidCommand::Key {
                code,
                pressed: true,
            });
            out.push(HidCommand::Key {
                code,
                pressed: false,
            });
            for &m in mods.iter().rev() {
                out.push(HidCommand::Key {
                    code: m,
                    pressed: false,
                });
            }
        }
        Some(out)
    }

    /// Characters in `text` this layout cannot type.
    pub fn missing(&self, text: &str) -> Vec<char> {
        let mut v: Vec<char> = text.chars().filter(|&c| self.keys(c).is_none()).collect();
        v.sort_unstable();
        v.dedup();
        v
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn s(l: &Layout, ch: char) -> Vec<(&'static str, bool, bool)> {
        l.strokes(ch)
            .unwrap_or_else(|| panic!("{} cannot type {ch:?}", l.name))
    }

    #[test]
    fn german_windows_altgr_and_swapped_keys() {
        let de = layout("de", Platform::Windows).unwrap();
        assert_eq!(s(&de, '|'), [("IntlBackslash", false, true)]);
        assert_eq!(s(&de, '@'), [("KeyQ", false, true)]);
        assert_eq!(s(&de, '\\'), [("Minus", false, true)]);
        assert_eq!(s(&de, '{'), [("Digit7", false, true)]);
        assert_eq!(s(&de, 'z'), [("KeyY", false, false)]);
        assert_eq!(s(&de, 'Z'), [("KeyY", true, false)]);
        // Dead key: then Space. Composition: dead key, then the letter.
        assert_eq!(
            s(&de, '^'),
            [("Backquote", false, false), ("Space", false, false)]
        );
        assert_eq!(
            s(&de, 'â'),
            [("Backquote", false, false), ("KeyA", false, false)]
        );
    }

    #[test]
    fn altgr_is_right_alt_alone() {
        let de = layout("de", Platform::Windows).unwrap();
        let keys = de.keys('|').unwrap();
        let codes: Vec<_> = keys
            .iter()
            .map(|k| match k {
                HidCommand::Key { code, pressed } => (*code, *pressed),
                other => panic!("{other:?}"),
            })
            .collect();
        assert_eq!(
            codes,
            [
                ("AltRight", true),
                ("IntlBackslash", true),
                ("IntlBackslash", false),
                ("AltRight", false),
            ]
        );
        assert!(!format!("{keys:?}").contains("Control"));
    }

    #[test]
    fn mac_german_uses_option() {
        let de = layout("de", Platform::Mac).unwrap();
        // On a Mac German keyboard, | is Option+7 and @ is Option+L.
        assert_eq!(s(&de, '|'), [("Digit7", false, true)]);
        assert_eq!(s(&de, '@'), [("KeyL", false, true)]);
        assert!(format!("{:?}", de.keys('@').unwrap()).contains("AltLeft"));
    }

    #[test]
    fn us_and_french_basics() {
        let us = layout("en-us", Platform::Windows).unwrap();
        assert_eq!(s(&us, '|'), [("Backslash", true, false)]);
        assert_eq!(s(&us, 'a'), [("KeyA", false, false)]);
        let fr = layout("fr", Platform::Windows).unwrap();
        assert_eq!(s(&fr, 'a'), [("KeyQ", false, false)]);
        assert_eq!(s(&fr, '1'), [("Digit1", true, false)]);
        assert_eq!(s(&fr, '@'), [("Digit0", false, true)]);
    }

    #[test]
    fn control_characters_and_missing() {
        let us = layout("en-us", Platform::Windows).unwrap();
        assert!(us.keys('\n').is_some());
        assert_eq!(us.keys('\r'), Some(Vec::new()));
        assert_eq!(us.missing("abc€😀"), vec!['€', '😀']);
        let de = layout("de", Platform::Windows).unwrap();
        assert!(de.missing("Grüße, ~|@€ 100%").is_empty());
    }

    #[test]
    fn every_table_is_sorted_and_has_the_basics() {
        for (name, platform, entries) in data::LAYOUTS {
            assert!(
                entries.windows(2).all(|w| w[0].0 < w[1].0),
                "{name} {platform:?} not sorted"
            );
            let l = layout(name, *platform).unwrap();
            for ch in ['1', ' ', '.'] {
                assert!(l.strokes(ch).is_some(), "{name} {platform:?} lacks {ch:?}");
            }
        }
        assert!(names().contains(&"de"));
    }
}
